public class AccountScoringJob implements Queueable {
    private List<Id> accountIds;
    private static final Integer BATCH_SIZE = 200;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Get the first batch (up to 200 IDs)
        List<Id> currentBatch = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < BATCH_SIZE) {
                currentBatch.add(accountIds.get(i));
            } else {
                remainingIds.add(accountIds.get(i));
            }
        }

        // Single SOQL query
        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentBatch
        ];

        // Rate the accounts
        for (Account acc : accountsToUpdate) {
            acc.Rating = getRating(acc.AnnualRevenue);
        }

        // Single DML statement
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }

        // Chain the next job if there are remaining IDs
        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    private String getRating(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
