public class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Load opportunities
        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Filter out those already Closed Won and prepare events
        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        List<Deal_Won__e> eventsToPublish = new List<Deal_Won__e>();

        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opportunitiesToClose.add(opp);
                eventsToPublish.add(
                    new Deal_Won__e(
                        Opportunity_Id__c = opp.Id,
                        Amount__c = opp.Amount
                    )
                );
            }
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        // Update opportunities and publish events in a single UoW
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        // Update opportunities
        for (Opportunity opp : opportunitiesToClose) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = System.today();
            uow.registerDirty(opp);
        }

        // Register events for publishing after transaction
        for (Deal_Won__e event : eventsToPublish) {
            uow.registerPublishAfterTransaction(event);
        }

        // Commit - this will save opportunities and publish events
        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
