trigger CaseTrigger on Case (after update) {
    List<Id> closedCaseIds = new List<Id>();

    // Detect cases that transitioned from open to closed
    for (Integer i = 0; i < Trigger.new.size(); i++) {
        Case newCase = Trigger.new[i];
        Case oldCase = Trigger.old[i];

        // IsClosed changed from false to true
        if (!oldCase.IsClosed && newCase.IsClosed && newCase.ContactId != null) {
            closedCaseIds.add(newCase.Id);
        }
    }

    // Batch cases into groups of 10 to avoid exceeding async job limits
    // while keeping reasonable isolation per batch
    Integer batchSize = 10;
    for (Integer i = 0; i < closedCaseIds.size(); i += batchSize) {
        Integer endIndex = Math.min(i + batchSize, closedCaseIds.size());
        List<Id> batch = closedCaseIds.subList(i, endIndex);
        System.enqueueJob(new CaseSurveyJob(batch));
    }
}
```

