public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * Imports a list of web gifts through NPSP's Data Import engine.
     * Each gift is staged as an NPSP Data Import record and processed synchronously.
     * Contact matching and household/donation creation follows the org's Data Import settings.
     * 
     * @param gifts List of WebGift objects to import
     * @return List of ImportResult objects in input order, one per gift
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        // Handle null or empty input
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage NPSP Data Import records
        List<npsp__DataImport__c> dataImports = stageDataImports(gifts);

        // Insert staged records
        insert dataImports;

        // Process the staged records through NPSP's Data Import engine
        processDataImports(dataImports);

        // Query back the processed records to build results
        List<npsp__DataImport__c> processedRecords = queryProcessedImports(
            new List<Id>(new Map<Id, npsp__DataImport__c>(dataImports).keySet())
        );

        // Build ImportResult objects from processed records, maintaining input order
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>(processedRecords);

        for (npsp__DataImport__c dataImport : dataImports) {
            npsp__DataImport__c processed = processedMap.get(dataImport.Id);
            results.add(buildImportResult(processed));
        }

        return results;
    }

    /**
     * Creates NPSP Data Import records from WebGift objects.
     */
    private static List<npsp__DataImport__c> stageDataImports(List<WebGift> gifts) {
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift.email;
            dataImport.npsp__Donation_Amount__c = gift.amount;
            dataImport.npsp__Donation_Date__c = gift.giftDate;
            dataImport.npsp__Donation_Donor__c = 'Contact1';

            dataImports.add(dataImport);
        }

        return dataImports;
    }

    /**
     * Processes staged Data Import records through NPSP's Data Import engine.
     * Uses the org's Data Import settings for matching and processing rules.
     */
    private static void processDataImports(List<npsp__DataImport__c> dataImports) {
        // NPSP provides the BDI_DataImport_API for processing data imports
        // This method respects the org's Data Import Settings and applies matching rules
        BDI_DataImport_API.processDataImportRecords(dataImports);
    }

    /**
     * Queries processed NPSP Data Import records to retrieve results.
     */
    private static List<npsp__DataImport__c> queryProcessedImports(List<Id> dataImportIds) {
        return [
            SELECT 
                Id,
                npsp__Status__c,
                npsp__Contact1Imported__c,
                npsp__DonationImported__c,
                npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImportIds
        ];
    }

    /**
     * Builds an ImportResult from a processed NPSP Data Import record.
     */
    private static ImportResult buildImportResult(npsp__DataImport__c dataImport) {
        ImportResult result = new ImportResult();

        if (dataImport == null) {
            result.success = false;
            result.errorMessage = 'Data Import record not found';
            return result;
        }

        // Success is determined by NPSP's status
        result.success = dataImport.npsp__Status__c == 'Imported';
        result.contactId = dataImport.npsp__Contact1Imported__c;
        result.opportunityId = dataImport.npsp__DonationImported__c;
        result.errorMessage = dataImport.npsp__FailureInformation__c;

        return result;
    }
}
