public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Handle null or empty input
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect unique opportunities and contacts
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Fetch opportunities
        Map<Id, Opportunity> opportunitiesMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c 
             FROM Opportunity 
             WHERE Id IN :opportunityIds]
        );

        // Query 2: Fetch existing OpportunityContactRole records
        Map<String, OpportunityContactRole> existingRolesMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + '_' + ocr.ContactId;
            existingRolesMap.put(key, ocr);
        }

        // Query 3: Fetch existing Partial Soft Credit records
        Map<String, npsp__Partial_Soft_Credit__c> existingSoftCreditsMap = 
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, 
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :opportunityIds 
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + '_' + psc.npsp__Contact__c;
            existingSoftCreditsMap.put(key, psc);
        }

        // Query 4: Fetch contacts
        Map<Id, Contact> contactsMap = new Map<Id, Contact>(
            [SELECT Id FROM Contact WHERE Id IN :contactIds]
        );

        // Validate all requests before any DML
        validateRequests(requests, opportunitiesMap, contactsMap);

        // Process requests: prepare contact roles and soft credits for upsert
        List<OpportunityContactRole> ocrToUpsert = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        Set<String> processedKeys = new Set<String>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '_' + req.contactId;

            // Avoid duplicate processing within this call
            if (processedKeys.contains(key)) {
                continue;
            }
            processedKeys.add(key);

            // Get or create OpportunityContactRole
            OpportunityContactRole ocr = existingRolesMap.get(key);
            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
            } else {
                ocr.Role = req.role;
            }
            ocrToUpsert.add(ocr);

            // Get or create Partial Soft Credit
            npsp__Partial_Soft_Credit__c psc = existingSoftCreditsMap.get(key);

            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role
                );
            } else {
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
            }
            softCreditsToUpsert.add(psc);
        }

        // DML: Upsert contact roles (DML 1)
        upsert ocrToUpsert;

        // Update soft credits with contact role IDs (DML 2)
        for (Integer i = 0; i < ocrToUpsert.size(); i++) {
            softCreditsToUpsert[i].npsp__Contact_Role_ID__c = ocrToUpsert[i].Id;
        }

        // DML: Upsert soft credits (DML 3)
        upsert softCreditsToUpsert;
    }

    private static void validateRequests(List<SoftCreditRequest> requests, 
                                         Map<Id, Opportunity> opportunitiesMap,
                                         Map<Id, Contact> contactsMap) {
        // Validate each request
        for (SoftCreditRequest req : requests) {
            // Validate amount
            if (req.amount == null) {
                throw new SoftCreditException('Amount cannot be null');
            }
            if (req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive');
            }

            // Validate opportunity exists
            Opportunity opp = opportunitiesMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }

            // Validate amount does not exceed opportunity amount
            if (req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount (' + req.amount + ') cannot exceed opportunity amount (' + opp.Amount + ')'
                );
            }

            // Validate contact is not the primary contact
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact cannot be the primary contact of the opportunity'
                );
            }

            // Validate contact exists
            if (!contactsMap.containsKey(req.contactId)) {
                throw new SoftCreditException('Contact not found: ' + req.contactId);
            }
        }
    }
}
```

I see the issue now. The problem is that we're creating contact roles via `OpportunityContactRole` records, but NPSP might also be auto-creating roles based on the `npsp__Primary_Contact__c` field. We're ending up with duplicate roles for the donor.

The solution is to NOT insert `OpportunityContactRole` records for the donor if we're already setting them as the primary contact via `npsp__Primary_Contact__c`. We should only add roles for the other household members.

