public class GiftService {

    /**
     * Records a gift (Closed Won donation) for a contact.
     * The gift is credited to the contact's household account with proper
     * contact roles and payment records as expected by NPSP.
     * 
     * @param contactId The Id of the contact making the gift
     * @param amount The donation amount
     * @param giftDate The date the gift was received
     * @return The Id of the created Opportunity
     * @throws IllegalArgumentException if contact doesn't exist, or amount is null/zero/negative
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate amount
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero');
        }

        // Fetch the contact to verify it exists and get household info
        Contact donor = getContact(contactId);
        if (donor == null) {
            throw new IllegalArgumentException('Contact does not exist');
        }

        // Get the household account for this contact
        Id householdAccountId = getHouseholdAccountId(contactId);

        // Create the opportunity
        Opportunity opp = createOpportunity(donor, householdAccountId, amount, giftDate);
        insert opp;

        // Add contact roles for household members (not the donor, NPSP handles that via Primary Contact)
        addHouseholdMemberRoles(opp.Id, contactId, getHouseholdMembers(householdAccountId));

        // Create payment record
        createPayment(opp.Id, amount, giftDate);

        return opp.Id;
    }

    /**
     * Fetches a contact by Id with relevant fields
     */
    private static Contact getContact(Id contactId) {
        try {
            List<Contact> contacts = [
                SELECT Id, FirstName, LastName, AccountId
                FROM Contact
                WHERE Id = :contactId
                LIMIT 1
            ];
            return contacts.isEmpty() ? null : contacts[0];
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Gets the household account for a contact.
     * In NPSP Household Account model, the contact's AccountId is the household.
     */
    private static Id getHouseholdAccountId(Id contactId) {
        Contact c = [SELECT AccountId FROM Contact WHERE Id = :contactId LIMIT 1];
        return c.AccountId;
    }

    /**
     * Creates an Opportunity record for the gift
     */
    private static Opportunity createOpportunity(
        Contact donor,
        Id householdAccountId,
        Decimal amount,
        Date giftDate
    ) {
        String formattedDate = giftDate.year() + '-' + 
                              String.valueOf(giftDate.month()).leftPad(2, '0') + '-' + 
                              String.valueOf(giftDate.day()).leftPad(2, '0');
        String oppName = donor.FirstName + ' ' + donor.LastName + ' Donation ' + formattedDate;

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdAccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            npsp__Primary_Contact__c = donor.Id
        );

        return opp;
    }

    /**
     * Gets all contacts in the household
     */
    private static Set<Id> getHouseholdMembers(Id householdAccountId) {
        Set<Id> memberIds = new Set<Id>();

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdAccountId
        ];

        for (Contact member : householdMembers) {
            memberIds.add(member.Id);
        }

        return memberIds;
    }

    /**
     * Adds contact roles for household members (not the donor).
     * NPSP automatically creates the Donor role via npsp__Primary_Contact__c,
     * so we only add Household Member roles for other members.
     */
    private static void addHouseholdMemberRoles(
        Id opportunityId,
        Id donorContactId,
        Set<Id> householdMemberIds
    ) {
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();

        // Add Household Member role for other household members only
        // Do NOT add a role for the donor - NPSP handles that via Primary Contact
        for (Id memberId : householdMemberIds) {
            if (memberId != donorContactId) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

