            npe01__Opportunity__c = opportunityId,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = paymentDate,
            npe01__Scheduled_Date__c = paymentDate,
            npe01__Paid__c = true
        );

        insert payment;
    }
}
