public inherited sharing class TA_Case_RollupOpenCount 
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        processRollup(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processRollup(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        processRollup(null, triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        processRollup(triggerNew, null);
    }

    private void processRollup(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Collect all affected Account IDs
        Set<Id> affectedAccountIds = new Set<Id>();

        if (triggerNew != null) {
            for (SObject caseRecord : triggerNew) {
                Id accountId = (Id) caseRecord.get('AccountId');
                if (accountId != null) {
                    affectedAccountIds.add(accountId);
                }
            }
        }

        if (triggerOld != null) {
            for (SObject caseRecord : triggerOld) {
                Id accountId = (Id) caseRecord.get('AccountId');
                if (accountId != null) {
                    affectedAccountIds.add(accountId);
                }
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        // Query 1: Get count of open cases per account
        Map<Id, Integer> accountIdToOpenCaseCount = new Map<Id, Integer>();

        // Initialize all affected accounts to 0
        for (Id accountId : affectedAccountIds) {
            accountIdToOpenCaseCount.put(accountId, 0);
        }

        // Count open cases per account using aggregate query
        String soqlQuery = 'SELECT AccountId, COUNT() caseCount FROM Case WHERE AccountId IN :affectedAccountIds AND IsClosed = false GROUP BY AccountId';
        List<AggregateResult> results = Database.query(soqlQuery);

        for (AggregateResult result : results) {
            Id accountId = (Id) result.get('AccountId');
            Integer caseCount = (Integer) result.get('caseCount');
            accountIdToOpenCaseCount.put(accountId, caseCount);
        }

        // Build accounts to update
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : affectedAccountIds) {
            Integer openCaseCount = accountIdToOpenCaseCount.get(accountId);
            accountsToUpdate.add(
                new Account(
                    Id = accountId,
                    FB_Open_Case_Count__c = openCaseCount
                )
            );
        }

        // DML: Update all affected accounts
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
