public class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact c : contacts) {
            // Only process contacts with an Account
            if (c.AccountId == null) {
                continue;
            }

            // Check if all four mailing fields are blank
            if (
                String.isBlank(c.MailingStreet)
                && String.isBlank(c.MailingCity)
                && String.isBlank(c.MailingPostalCode)
                && String.isBlank(c.MailingCountry)
            ) {
                // Get the parent account
                Account parentAccount = accountsById.get(c.AccountId);
                if (parentAccount != null) {
                    // Copy billing address to mailing address
                    c.MailingStreet = parentAccount.BillingStreet;
                    c.MailingCity = parentAccount.BillingCity;
                    c.MailingPostalCode = parentAccount.BillingPostalCode;
                    c.MailingCountry = parentAccount.BillingCountry;
                }
            }
        }
    }
}
